require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];$role=$_POST['role'];$hash=password_hash($pass,PASSWORD_DEFAULT);$pdo->prepare("INSERT INTO users(name,email,password,role,status) VALUES(?,?,?,?, 'active')")->execute([$name,$email,$hash,$role]);flash('success','User created.');header("Location:index.php");exit;}
$rows=$pdo->query("SELECT id,name,email,role,status,created_at FROM users ORDER BY id DESC")->fetchAll();$page_title='Users';require __DIR__.'/../partials/header.php';?>
<h3 class="fw-bold">Users</h3><p class="text-muted">Manage system access.</p><div class="row g-3"><div class="col-md-4"><div class="card p-3"><h6>Add User</h6><form method="post"><input class="form-control mb-2" name="name" required placeholder="Name"><input class="form-control mb-2" type="email" name="email" required placeholder="Email"><input class="form-control mb-2" type="password" name="password" required placeholder="Password"><select class="form-select mb-2" name="role"><option>cashier</option><option>manager</option><option>admin</option></select><button class="btn btn-primary w-100">Create</button></form></div></div><div class="col-md-8"><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e(ucfirst($r['role']))?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
